describe('Service Collaboration', () => {
  it('should coordinate with dependencies properly', async () => {
    const orchestrator = new ServiceOrchestrator(
      mockServiceA,
      mockServiceB,
      mockServiceC
    );

    await orchestrator.execute(task);

