  it('should adapt to new collaboration requirements', () => {
    const enhancedMock = extendSwarmMock(baseMock, {
      newMethod: jest.fn().mockResolvedValue(expectedResult)
    });

    expect(enhancedMock).toSatisfyContract(updatedContract);
